// экран «תוכן» в админке (#686cecdc) и автофильтр (#2ee07c55).
// Аккаунты: user4 (приложение, iPhone 13 Mini WebKit-дескриптор), admin (админка, десктоп 1440×900). Других аккаунтов нет.
// Селекторы и тексты сверены на живых сайтах 12.11 (magnet.expo.app, magnet-admin.vercel.app).
import { expect, devices, type Browser, type Locator, type Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { captureApi, type Api } from '../_shared/api';
import { saveSession } from '../_shared/session';
import { tap } from '../post-create/post-helpers';

export const ADMIN_URL = 'https://magnet-admin.vercel.app';
export const authFile = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

// Демо-публикации сида (не реальные пользователи; id вида 00000000-0000-4000-8000-…): пост «רוני» в общем фиде.
export const DEMO_POST = { id: '00000000-0000-4000-8000-0000000a0008', author: 'רוני', authorId: '00000000-0000-4000-8000-000000000029', text: /^הבניין הכי יפה בתל אביב/ };

export function baseUrl(): string {
  const cfg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
  return process.env.QA_BASE_URL || cfg.baseUrl;
}

// Короткая случайная метка из букв (слово для списка запрещённых — без цифр).
export const tag = (n = 6) => Array.from({ length: n }, () => 'abcdefghijklmnopqrstuvwxyz'[Math.floor(Math.random() * 26)]).join('');
export const qaText = (ticket: string, label: string) => `QA-AUTO ${ticket} ${label} ${tag(5)}`;
// Короткий номер контента в админке: «C-» + последние 6 символов id в верхнем регистре.
export const cId = (id: string) => `C-${id.replace(/-/g, '').slice(-6).toUpperCase()}`;

// ---------- приложение (user4) ----------

// Тап по элементу ленты: сначала прокрутить его в центр экрана (иначе низ ленты под нижней панелью вкладок),
// потом тап, когда элемент — верхний в своей точке (tap из post-helpers ждёт ухода сплэша).
// Шторки (меню, окна) выезжают снизу с анимацией — ждём, пока рамка элемента перестанет двигаться.
export async function tapIn(page: Page, target: Locator) {
  await expect(target).toBeVisible();
  await target.evaluate((el) => el.scrollIntoView({ block: 'center' }));
  let prev = '';
  await expect
    .poll(async () => {
      const b = await target.boundingBox();
      const cur = b ? `${Math.round(b.x)},${Math.round(b.y)},${Math.round(b.width)},${Math.round(b.height)}` : '';
      const same = !!cur && cur === prev;
      prev = cur;
      return same;
    }, { message: 'элемент всё ещё движется (анимация шторки)', intervals: [100, 100, 150, 250] })
    .toBe(true);
  await tap(page, target);
}

// Окно роли на iPhone 13 Mini: @data-тесты идут в проекте data (десктоп), поэтому устройство задаём явно.
export async function iphoneAs(browser: Browser, role: string): Promise<Page> {
  const storageState = authFile(role);
  if (!fs.existsSync(storageState)) throw new Error(`Нет сессии «${role}» (.qa/auth/${role}.json) — npm run qa-login:manual -- ${role}`);
  const { defaultBrowserType: _b, ...iphone } = devices['iPhone 13 Mini'];
  void _b;
  const ctx = await browser.newContext({ ...iphone, locale: 'he-IL', baseURL: baseUrl(), storageState });
  return ctx.newPage();
}

export async function closeApp(page: Page | undefined, role: string) {
  if (!page || page.isClosed()) return;
  await saveSession(page, role);
  await page.context().close();
}

// Токен пользователя берётся из настоящего запроса приложения (см. _shared/api.ts).
export const appApi = (page: Page, url = '/social') => captureApi(page, url);

const h = (api: Api, extra: Record<string, string> = {}) => ({ apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json', ...extra });

// Пост тем же запросом, что отправляет приложение при «לפרסם» (POST /rest/v1/posts?select=id, тело как в приложении).
export async function createPost(api: Api, body: string): Promise<string> {
  const res = await api.page.request.post(`${api.base}/rest/v1/posts?select=id`, {
    headers: h(api, { Prefer: 'return=representation' }),
    data: { author_id: api.userId, body, image_url: null, extra_image_urls: [] },
    failOnStatusCode: false,
  });
  expect(res.status(), `создание поста: ${await res.text()}`).toBe(201);
  return String((await res.json())[0].id);
}

export async function deletePost(api: Api, id: string) {
  if (api.page.isClosed()) return;
  await api.page.request.delete(`${api.base}/rest/v1/posts?id=eq.${id}`, { headers: h(api), failOnStatusCode: false });
}

export async function postVisibleToAuthor(api: Api, id: string): Promise<boolean> {
  const res = await api.page.request.get(`${api.base}/rest/v1/posts?id=eq.${id}&select=id`, { headers: h(api), failOnStatusCode: false });
  return res.ok() && (await res.json()).length === 1;
}

// Сообщение в общем чате тем же запросом, что «שליחה» в приложении.
export async function sendCommunity(api: Api, body: string): Promise<string> {
  const res = await api.page.request.post(`${api.base}/rest/v1/community_messages?select=id`, {
    headers: h(api, { Prefer: 'return=representation' }),
    data: { author_id: api.userId, body },
    failOnStatusCode: false,
  });
  expect(res.status(), `сообщение в общем чате: ${await res.text()}`).toBe(201);
  return String((await res.json())[0].id);
}

export async function deleteCommunity(api: Api, ids: string[]) {
  if (!ids.length || api.page.isClosed()) return;
  await api.page.request.delete(`${api.base}/rest/v1/community_messages?id=in.(${ids.join(',')})`, { headers: h(api), failOnStatusCode: false });
}

export async function myReportByDetails(api: Api, details: string): Promise<{ id: string; status: string } | undefined> {
  const res = await api.page.request.get(`${api.base}/rest/v1/reports?reporter_id=eq.${api.userId}&details=eq.${encodeURIComponent(details)}&select=id,status`, { headers: h(api), failOnStatusCode: false });
  const rows = res.ok() ? await res.json() : [];
  return rows[0];
}

export async function unblock(api: Api, blockedId: string) {
  if (api.page.isClosed()) return;
  await api.page.request.delete(`${api.base}/rest/v1/blocks?blocked_id=eq.${blockedId}`, { headers: h(api), failOnStatusCode: false });
}

// ---------- админка (admin) ----------

export async function adminAs(browser: Browser): Promise<Page> {
  const storageState = authFile('admin');
  if (!fs.existsSync(storageState)) throw new Error('Нет сессии admin (.qa/auth/admin.json) — npm run qa-login:manual -- admin');
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, locale: 'he-IL', colorScheme: 'light', storageState });
  return ctx.newPage();
}

// Сессия админки — в cookie (Supabase SSR); refresh-токен одноразовый, поэтому после теста записываем свежую обратно.
export async function saveAdmin(page: Page | undefined) {
  if (!page || page.isClosed()) return;
  try {
    const state = await page.context().storageState();
    if (state.cookies.some((c) => /auth-token/.test(c.name) && c.domain.includes('magnet-admin'))) {
      fs.writeFileSync(authFile('admin'), JSON.stringify(state, null, 2));
    }
  } catch {
    // сохранение сессии не должно скрывать результат теста
  }
}

export async function closeAdmin(page: Page | undefined) {
  if (!page || page.isClosed()) return;
  await saveAdmin(page);
  await page.context().close();
}

export const contentQueue = (page: Page) => page.getByRole('region', { name: 'תור התוכן' });
export const contentDetail = (page: Page) => page.getByRole('region', { name: 'התוכן הנבחר' });
export const contentAside = (page: Page) => page.getByRole('complementary', { name: 'פרטי התוכן' });
export const queueLink = (page: Page, text: string) => contentQueue(page).getByRole('link', { name: new RegExp(text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')) });

export async function openContent(page: Page, query = '') {
  await page.goto(`${ADMIN_URL}/content${query}`);
  await expect(page.getByRole('heading', { name: 'תוכן', level: 1 })).toBeVisible();
}

// Диалог «מילים אסורות» (кнопка «מילים אסורות N» над вкладками).
export async function openBannedWords(page: Page) {
  await page.getByRole('button', { name: /^מילים אסורות/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'מילים אסורות' })).toBeVisible();
  return dlg;
}

export async function removeBannedWord(page: Page, word: string) {
  await openContent(page);
  const dlg = await openBannedWords(page);
  const btn = dlg.getByRole('button', { name: `הסרת ${word}` });
  if (await btn.count()) {
    await btn.click();
    await expect(btn).toHaveCount(0);
  }
}
